local PoolManager   = CS.Engine.Lib.PoolManager
local CDTimerModule = CS.Engine.Modules.CDTimerModule

local POOL_MAX = 0

--- from: Assets/BundleResources/Prefabs/CultivateOversea/CultivateOverseaTipsPanel.prefab
---@class CardProgressionAutoTips
---@field Env                           	CardProgressionAutoTips                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgArrow                      	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform
---@field ContentText                   	UnityEngine.RectTransform
local CardProgressionAutoTips = Class('CardProgressionAutoTips')


function CardProgressionAutoTips:__init()
    self.closeTimer_ = nil
    self.animeTimer_ = nil
end


function CardProgressionAutoTips:__delete()
    self.closeTimer_ = nil
    self.animeTimer_ = nil
end


function CardProgressionAutoTips:Awake()
    self.controller.ClearCache = false
    -- reset view
    CfUtils.FillText(self.ContentText, '')
    -- reset anim
    CfUtils.PlayAnimator(self.Root, 'CultivateOverseaTipsPanel_Go')
end


--- 显示一tips的方法调用
---@param point integer 战斗力变化
---@param rTimeLength number 显示时长
function CardProgressionAutoTips:ShowHUD(point, rTimeLength)
    local isIncrease = checkInt(point) >= 0
    local text = ''
    if isIncrease then
        text = localize("战斗力+_num_", {_num_ = point})
    else
        text = localize("战斗力_num_", {_num_ = point})
    end
    CfUtils.FillText(self.ContentText, text)
    CfUtils.SetUISwitchImage(self.ImgArrow, isIncrease and 1 or 2)
    CfUtils.SetUISwitchText(self.ContentText, isIncrease and 1 or 2)

    local closeInterval = checkInt(rTimeLength)
    self.closeTimer_ = CDTimerModule.GetInstance():AddCD(closeInterval, function(i, t)
        if not isNull(self) and not isNull(self.controller) then
            PoolManager.Instance:GiveBack(self.controller.gameObject, POOL_MAX)
        end
    end)

    local exitAnimTime  = CfUtils.GetAnimatorTime(self.Root, 'CultivateOverseaTipsPanel_Out')
    local doAnimIntaval = math.floor(math.max(closeInterval - exitAnimTime, 0))  -- cd 只能是 int 值，所以只能小数部分社区，提早播放动画
    self.animeTimer_ = CDTimerModule.GetInstance():AddCD(doAnimIntaval, function(i, t)
        if not isNull(self) and not isNull(self.controller) then
            CfUtils.PlayAnimator(self.Root, 'CultivateOverseaTipsPanel_Out')
        end
    end)
end


function CardProgressionAutoTips:OnDestroy()
    ---加回到对象池中去
    if not isNull(self.closeTimer_) then
        CDTimerModule.GetInstance():RemoveCD(self.closeTimer_)
        self.closeTimer_ = nil
    end
    if not isNull(self.animeTimer_) then
        CDTimerModule.GetInstance():RemoveCD(self.animeTimer_)
        self.animeTimer_ = nil
    end
    self:Delete()
    self.controller = nil--luabehaviour 中CSharp对象
    self = nil
end


return CardProgressionAutoTips